int[] noten = { 1, 4, 2, 5, 3, 2 };

// mit Schleife
var gute = new List<int>();
foreach (int n in noten)
{
    if (n <= 2) gute.Add(n);
}

// mit LINQ
var guteLinq = noten.Where(n => n <= 2).ToList();

Console.WriteLine(string.Join(" ", gute));
Console.WriteLine(string.Join(" ", guteLinq));
// Ausgabe:
// 1 2 2
// 1 2 2

var preise = new List<int> { 10, 25, 40 };
var mitRabatt = preise.Select(p => p - 5).ToList();
var texte = preise.Select(p => $"{p} Euro").ToList();

Console.WriteLine(string.Join(", ", mitRabatt));
Console.WriteLine(string.Join(", ", texte));
Console.WriteLine(string.Join(", ", preise));   // unverändert!
// Ausgabe:
// 5, 20, 35
// 10 Euro, 25 Euro, 40 Euro
// 10, 25, 40

var klasse = new List<Schueler>
{
    new Schueler("Lena", 87),
    new Schueler("Ali", 45),
    new Schueler("Mia", 92),
    new Schueler("Tom", 61)
};

var bestanden = klasse
    .Where(s => s.Punkte >= 50)
    .OrderByDescending(s => s.Punkte)
    .Select(s => s.Name)
    .ToList();

Console.WriteLine(string.Join(", ", bestanden));
// Ausgabe: Mia, Lena, Tom

class Schueler
{
    public string Name { get; }
    public int Punkte { get; }
    public Schueler(string name, int punkte)
    {
        Name = name;
        Punkte = punkte;
    }
}

int[] wuerfe = { 6, 2, 6, 4, 1, 6 };
Console.WriteLine(wuerfe.Count());
Console.WriteLine(wuerfe.Count(w => w == 6));
Console.WriteLine(wuerfe.Where(w => w > 3).Count());
// Ausgabe:
// 6
// 3
// 4

